  "frp.wait": "Saved, waiting for the phone.",
  "frp.off": "Off: Google's default protection only.",
  "no.frp": "the factory reset lock",
  "more.h": "More blocking", "ni.h": "New apps", "ni.off": "Can install, opens right away", "ni.ask": "Can install, blocked until approved", "ni.none": "Can't install", "more.loc": "Lock location: can't turn off location", "more.air": "Airplane mode: can't turn on",
  "dns.ss": "forces SafeSearch", "dns.custom": "Custom host…", "dns.novpn": "Block VPN apps and VPN settings", "dns.novpn.short": "VPN blocked", "dns.novpn.tip": "Stops the child from adding or turning on a VPN (a VPN would skip Safe DNS). Does not remove a VPN app that is already installed and approved. Our own remote-access VPN keeps working. Firefox, Brave and Opera ignore the \u201cno browser DoH\u201d setting we push to Chrome and Edge, so with them only this lock plus Private DNS help.",
  "dns.h": "Safe DNS (blocks adult sites)", "dns.pause": "Pause 30 min", "dns.pausedLeft": "Paused: {0} min left", "dns.resume": "Turn back on now", "dns.tip": "Blocks adult sites and turns on safe search. Works on both Wi-Fi and mobile data (via Android's Private DNS).",
  "kw.bank.h": "bank, banking, wallet, e-wallet, paypal, carrier, mobile operator, stocks, trading, game, won't open, does not open, blocked, crash, error, accessibility, vpn, usb debugging, adb, developer, root", "kw.anti.h": "uninstall, remove app, install app, new apps, developer options, adb, debugging, usb, wrong pin photo, intruder", "kw.dns.h": "adult, porn, nsfw, web filter, block websites, safe search, youtube restricted, vpn", "kw.more.h": "airplane, flight mode, location, gps, new apps", "kw.hm.h": "launcher, home screen, icons, wallpaper, notification shade", "kw.kn.h": "lock screen, message, phone number, contact, lost phone, found phone", "kw.daily.h": "screen time, play time, daily limit, usage limit", "kw.bed.h": "bedtime, sleep, night", "kw.wd.h": "grayscale, black and white, wind down", "kw.sch.h": "school, study, homework, class", "kw.chore.h": "chores, tasks, rewards, points, stars", "kw.zone.h": "zone, geofence, home, school, arrive, leave", "kw.trk.h": "route, track, location history", "kw.relay.h": "remote, away from home, mobile data, cloudflare, internet", "kw.ts.h": "tailscale, vpn, remote", "kw.tg.h": "telegram, bot, messages, alerts, chat", "kw.pin.h": "password, pin code, change pin, forgot pin", "kw.totp.h": "google authenticator, 6-digit code, two factor, 2fa, otp", "kw.sys.h": "volume, ringer, brightness, screen timeout, do not disturb, silent", "kw.dev.h": "developer options, adb, usb debugging", "kw.upd.h": "update, version, new version", "kw.ft.h": "permissions, features, device owner, basic mode", "kw.paired.h": "paired devices, parent phones, pairing", "kw.set.danger": "uninstall kidguard, remove kidguard, unpair, release, reset", "bank.h": "Apps that won't open (banks, wallets, carriers…)", "bank.colApp": "App", "bank.colAcc": "Access.", "bank.colAccDev": "Access. + debug", "bank.colDev": "Debug", "bank.colTcp": "adb port", "bank.tcpP": "Adb port column: for apps that also check adb over the network (e.g. My MobiFone). Tick it only if Debug alone isn't enough. The port comes back only on Wi-Fi or a USB cable, not on mobile data.", "bank.p": "Some apps (banks, wallets, carriers, a few games) won't open while Accessibility, USB debugging or a VPN is on. Tick the column the app complains about. When the kid opens the app, only that is paused, and the kid is told. It comes back 1 min (basic mode) or 10 min (Device Owner) after the kid leaves the app. Accessibility off: no screen view or control; time limits and app locks still work. Debugging off: the first open waits about 1 s (the kid sees \"Turning off USB debugging…\"), and adb to the phone drops meanwhile. Pick any app on the child's phone, or type a package name.", "bank.n": { one: "{0} app listed · tap to choose", other: "{0} apps listed · tap to choose" }, "bank.find": "Find an app", "bank.pkg": "Package name, e.g. com.VCB", "bank.add": "Add", "bank.bad": "Not a valid package name (like com.name.app)", "bank.goneH": "Not installed on the child phone ({0})", "bank.notInst": "not installed", "bank.acc": "Accessibility", "bank.vpnP": "VPN column: for apps that won't open with a VPN on (e.g. Cake). When the kid opens one, KidGuard turns Tailscale off (Device Owner: also lifts \"Always-on VPN\", then sets it back). It comes back together with Accessibility. Meanwhile Tailscale access is off; relay and Telegram still work. Other VPNs can't be turned off.", "bank.vpnStuck": "A VPN stayed on while the kid opened a banking app. It is either a VPN other than Tailscale, or \"Always-on VPN\" set in the child phone's Settings (basic mode can't lift it). Fix: turn Always-on off in Settings → Network → VPN on the child's phone.",
  "live.accBank": "Accessibility paused while the kid uses {0}. Back 10 minutes after they leave the app",
  "anti.h": "Anti-bypass", "anti.debug": "Block Developer options / ADB", "anti.shot": "Photo of whoever enters a wrong PIN", "anti.shotTip": "3 wrong PINs / codes on the child phone's management page: the phone takes one front-camera photo and attaches it to the alert in Recent. The PIN box says so; Android shows its camera dot. Kept 7 days on the child phone. Basic mode: allow the camera once after opening with the right PIN.", "shot.btn": "View photo", "shot.h": "Photo at the wrong PIN", "shot.wait": "Loading the photo…", "shot.waitRelay": "Waiting for the child phone to send it over the relay (when it is online, usually < 1 min)…", "shot.note": "Kept on the child phone for 7 days, then deleted.", "shot.gone": "The photo is no longer on the child phone (over 7 days, or released).",
