  "sh.h": "adb commands", "sd.sh": "Run shell commands on your kid's phone remotely", "sh.on": "ready", "sh.off": "not available",
  "sh.cant": "Needs on-phone adb (Android 11+, \"adb on phone\" paired, secure-settings permission, phone on Wi-Fi). Or open adb port 5555 (once on Wi-Fi, or adb tcpip 5555 over a cable): then it also works on mobile data.",
  "sh.p": "Each command runs as adb shell on your kid's phone and needs the PIN. The output shows here after a few seconds (longer over the relay). Commands stop after 25 seconds.",
  "sh.run": "Run", "sh.busy": "Running…", "sh.ask": "Run this command on your kid's phone?\n\n$ {0}", "sh.sent": "Command sent",
  "sh.clear": "Clear history", "sh.cleared": "Cleared", "sh.empty": "(no output)", "sh.errX": "Error: {0}",
  "sh.err.adb": "Couldn't run it (adb didn't answer or took over 25 seconds)", "sh.err.wifi": "The kid's phone isn't on Wi-Fi: Wireless debugging can't start. To run commands on mobile data, open port 5555 while on Wi-Fi (or adb tcpip 5555 over a cable)",
  "sh.err.wss": "Missing the secure-settings permission", "sh.err.blocked": "Debugging is blocked (rule \"Block debugging\")", "sh.err.key": "On-phone adb isn't paired yet", "sh.err.sdk": "Needs Android 11 or newer",
  "sh.tcp": "Open adb port 5555 (connect a computer without a cable)", "sh.tcpOn": "port 5555 open",
  "sh.tcpP": "Same as adb tcpip 5555, but the phone does it itself, also after a restart. USB debugging stays on (off while a banking app is open). A new computer must still be allowed on the phone. While the port is open, the adb commands above also work over mobile data. After a restart it needs Wi-Fi once to reopen. Turn it off when done.",
  "sh.tcpUp": "Open. On a computer on the same Wi-Fi, run:", "sh.tcpWait": "Opening the port… (needs Wi-Fi, can take a few minutes)", "sh.tcpPend": "port 5555 waiting", "sh.tcpNow": "Open now", "sh.tcpWhy.bank": "Waiting: a bank app (adb port column) closed it. Tap Open now once you have left that app.", "sh.tcpWhy.link": "No adb link: the port is closed and Wireless debugging needs Wi-Fi. Join any Wi-Fi (internet not needed), then tap Open now. Or plug in a computer and run adb tcpip 5555.",
  "sh.tcpAsk": "Open adb port 5555 on the kid's phone? Anyone on the same Wi-Fi can see it, and your kid can allow any computer on the phone with one tap: that computer then controls the phone. Open it only while you need it.", "sh.tcpUntil": "open until {0}", "sh.tcpBtn": "Open port",
  "sh.tcpAskOff": "Close adb port 5555 and put Developer options back as they were?", "sh.tcpOffBtn": "Close port",
